#include <bits/stdc++.h>
using namespace std;

const long long MODULUS = 998244353;
vector<long long> wArr, wArrInv;

long long modExp(long long base, long long exp) {
    long long res = 1;
    long long b = base % MODULUS;
    long long e = exp;
    while (e > 0) {
        if (e & 1)
            res = (res * b) % MODULUS;
        b = (b * b) % MODULUS;
        e >>= 1;
    }
    return res;
}

void prepare() {
    wArr.resize(21);
    wArrInv.resize(21);
    for (int h = 0; h <= 20; h++) {
        wArr[h] = modExp(3, (MODULUS - 1) >> h);
        wArrInv[h] = modExp(3, (MODULUS - 1) - ((MODULUS - 1) >> h));
    }
}

void fftTransform(vector<long long>& data, int length, bool invert) {
    for (int i = 1, j = 0; i < length; i++) {
        int mask = length;
        do {
            j ^= mask >>= 1;
        } while ((j & mask) == 0);
        if (i < j) {
            swap(data[i], data[j]);
        }
    }
    for (int h = 0, size; (size = 1 << h) < length; h++) {
        long long wFactor = invert ? wArrInv[h + 1] : wArr[h + 1];
        for (int start = 0; start < length; start += size * 2) {
            long long w = 1;
            for (int j = 0; j < size; j++) {
                int leftIdx = start + j;
                int rightIdx = leftIdx + size;
                long long u = data[leftIdx];
                long long v = data[rightIdx] * w % MODULUS;
                data[leftIdx] = (u + v) % MODULUS;
                data[rightIdx] = (u - v + MODULUS) % MODULUS;
                w = w * wFactor % MODULUS;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    prepare();
    int nDiv2, kCount;
    cin >> nDiv2 >> kCount;
    int nSize = 1;
    while (nSize < nDiv2 * 9 + 1)
        nSize <<= 1;
    vector<long long> arr(nSize, 0);
    for (int i = 0; i < kCount; i++) {
        int d;
        cin >> d;
        arr[d] = 1;
    }
    fftTransform(arr, nSize, false);
    for (int i = 0; i < nSize; i++) {
        arr[i] = modExp(arr[i], nDiv2);
    }
    fftTransform(arr, nSize, true);
    long long invN = modExp(nSize, MODULUS - 2);
    vector<long long> result(nSize);
    for (int i = 0; i < nSize; i++) {
        arr[i] = (arr[i] * invN) % MODULUS;
        result[i] = arr[i];
    }
    long long sumResult = 0;
    for (int i = 0; i <= nDiv2 * 9; i++) {
        long long val = result[i];
        sumResult = (sumResult + val * val) % MODULUS;
    }
    cout << sumResult << "\n";
    return 0;
}

